import type {
  SurveyAnswerValue,
  SurveyAnswers,
  SurveyConfig,
  SurveyQuestion,
  SurveySubmission,
  SurveyTrigger,
} from "../../core/types.js";

/** A single validation problem. */
export interface SurveyValidationIssue {
  readonly questionId: string;
  readonly message: string;
}

/** Storage used to remember surveys that were already shown. */
export interface SurveyStoreOptions {
  readonly storage?: Storage | null;
  readonly key?: string;
}

/** Small best-effort persistence helper for "show once" surveys. */
export interface SurveyStore {
  readonly key: string;
  wasShown(): boolean;
  markShown(): void;
  clear(): void;
}

const CHOICE_TYPES = new Set(["radio", "checkbox", "select"]);

function defaultTitle(kind: SurveyConfig["kind"]): string {
  switch (kind) {
    case "feedback":
      return "Feedback";
    case "review":
      return "Review";
    case "quiz":
      return "Quiz";
    case "survey":
    default:
      return "Survey";
  }
}

/** Returns true when a question renders a list of options. */
export function isChoiceQuestion(question: SurveyQuestion): boolean {
  return CHOICE_TYPES.has(question.type);
}

/** Returns true when a question is required by default or explicitly. */
export function isRequiredQuestion(question: SurveyQuestion): boolean {
  return question.required === true;
}

/** The stable id used by a survey. */
export function surveyId(survey: SurveyConfig): string {
  if (survey.id !== undefined && survey.id.length > 0) {
    return survey.id;
  }

  return `${survey.kind ?? "survey"}:${survey.title ?? defaultTitle(survey.kind)}`;
}

/** Fills defaults so the UI and the event payloads are predictable. */
export function normalizeSurvey(survey: SurveyConfig): SurveyConfig {
  const kind = survey.kind ?? "survey";
  const required = survey.required ?? survey.blocking ?? false;
  const allowSkip = survey.allowSkip ?? !required;

  return {
    ...survey,
    id: surveyId(survey),
    kind,
    title: survey.title ?? defaultTitle(kind),
    submitLabel: survey.submitLabel ?? "Submit",
    skipLabel: survey.skipLabel ?? "Skip",
    closeLabel: survey.closeLabel ?? "Close",
    thankYouTitle: survey.thankYouTitle ?? "Thank you!",
    thankYouText: survey.thankYouText ?? "",
    trigger: survey.trigger ?? "ended",
    once: survey.once ?? true,
    allowSkip,
    required,
    blocking: survey.blocking ?? required,
    submitMode: survey.submitMode ?? (survey.autoSubmit === true ? "on-select" : "manual"),
    autoSubmitDelay: Math.max(0, survey.autoSubmitDelay ?? 0),
    instantFeedback: survey.instantFeedback ?? kind === "quiz",
    allowRetake: survey.allowRetake ?? survey.allowResubmit ?? false,
    ...(survey.maxAttempts === undefined ? {} : { maxAttempts: survey.maxAttempts }),
  };
}

/** Converts a trigger into a time in seconds, or null for lifecycle triggers. */
export function surveyTriggerTime(trigger: SurveyTrigger | undefined): number | null {
  if (typeof trigger === "number") {
    return Number.isFinite(trigger) ? Math.max(0, trigger) : null;
  }

  if (typeof trigger === "object" && trigger !== null) {
    return Number.isFinite(trigger.at) ? Math.max(0, trigger.at) : null;
  }

  return null;
}

/** Returns a value describing an untouched answer for a question. */
export function emptySurveyAnswer(question: SurveyQuestion): SurveyAnswerValue {
  switch (question.type) {
    case "checkbox":
      return [];
    case "rating":
    case "scale":
      return question.min ?? (question.type === "rating" ? 0 : 0);
    case "radio":
    case "select":
    case "text":
    case "textarea":
    default:
      return "";
  }
}

/** Creates an answer map with every question initialised. */
export function createSurveyAnswers(survey: SurveyConfig): SurveyAnswers {
  const answers: Record<string, SurveyAnswerValue> = {};

  for (const question of survey.questions) {
    answers[question.id] = emptySurveyAnswer(question);
  }

  return answers;
}

/** Normalizes arbitrary input into a safe answer map. */
export function normalizeSurveyAnswers(
  survey: SurveyConfig,
  answers: Readonly<Record<string, unknown>>,
): SurveyAnswers {
  const result: Record<string, SurveyAnswerValue> = {};

  for (const question of survey.questions) {
    const value = answers[question.id];

    if (question.type === "checkbox") {
      const list = Array.isArray(value)
        ? value.filter((entry): entry is string => typeof entry === "string")
        : typeof value === "string" && value.length > 0
          ? [value]
          : [];
      result[question.id] = list;
      continue;
    }

    if (question.type === "rating" || question.type === "scale") {
      const numeric = typeof value === "number" ? value : Number(value);
      result[question.id] = Number.isFinite(numeric) ? numeric : (question.min ?? 0);
      continue;
    }

    result[question.id] =
      typeof value === "string"
        ? value
        : typeof value === "number" || typeof value === "boolean"
          ? String(value)
          : "";
  }

  return result;
}

/** Returns true when an answer has no meaningful value. */
export function isSurveyAnswerEmpty(question: SurveyQuestion, value: SurveyAnswerValue): boolean {
  if (question.type === "checkbox") {
    return !Array.isArray(value) || value.length === 0;
  }

  if (question.type === "rating" || question.type === "scale") {
    const number = typeof value === "number" ? value : Number(value);
    return !Number.isFinite(number) || number <= (question.min ?? 0);
  }

  if (value === null || value === undefined) {
    return true;
  }

  return String(value).trim().length === 0;
}

/** Validates answers and returns readable issues. */
export function validateSurveyAnswers(
  survey: SurveyConfig,
  answers: SurveyAnswers,
): readonly SurveyValidationIssue[] {
  const issues: SurveyValidationIssue[] = [];

  for (const question of survey.questions) {
    const value = answers[question.id] ?? emptySurveyAnswer(question);

    if (isRequiredQuestion(question) && isSurveyAnswerEmpty(question, value)) {
      issues.push({ questionId: question.id, message: "This question is required." });
      continue;
    }

    if (question.type === "text" || question.type === "textarea") {
      const text = typeof value === "string" ? value : String(value ?? "");

      if (question.minLength !== undefined && text.length < question.minLength) {
        issues.push({
          questionId: question.id,
          message: `Enter at least ${question.minLength} characters.`,
        });
      }

      if (question.maxLength !== undefined && text.length > question.maxLength) {
        issues.push({
          questionId: question.id,
          message: `Enter at most ${question.maxLength} characters.`,
        });
      }
    }

    if (question.type === "checkbox" && Array.isArray(value)) {
      if (question.minSelections !== undefined && value.length < question.minSelections) {
        issues.push({
          questionId: question.id,
          message: `Select at least ${question.minSelections} options.`,
        });
      }

      if (question.maxSelections !== undefined && value.length > question.maxSelections) {
        issues.push({
          questionId: question.id,
          message: `Select at most ${question.maxSelections} options.`,
        });
      }
    }

    if (question.type === "rating" || question.type === "scale") {
      const number = typeof value === "number" ? value : Number(value);

      if (
        Number.isFinite(number) &&
        ((question.min !== undefined && number < question.min) ||
          (question.max !== undefined && number > question.max))
      ) {
        issues.push({ questionId: question.id, message: "The selected value is out of range." });
      }
    }
  }

  return issues;
}

/** Returns true when every required question has a valid answer. */
export function isSurveyComplete(survey: SurveyConfig, answers: SurveyAnswers): boolean {
  return validateSurveyAnswers(survey, answers).length === 0;
}

function normalizeComparable(value: SurveyAnswerValue): string | readonly string[] | number {
  if (Array.isArray(value)) {
    return value.map((entry) => entry.trim().toLowerCase()).sort((a, b) => a.localeCompare(b));
  }

  if (typeof value === "number") {
    return value;
  }

  return String(value ?? "")
    .trim()
    .toLowerCase();
}

/** Evaluates an answer against `question.correct`, or null when not a quiz. */
export function evaluateSurveyAnswer(
  question: SurveyQuestion,
  value: SurveyAnswerValue,
): { readonly correct: boolean; readonly explanation: string } | null {
  if (question.correct === undefined) {
    return null;
  }

  const expected = question.correct;
  const actual = normalizeComparable(value);
  let correct = false;

  if (Array.isArray(expected)) {
    const wanted = expected
      .map((entry) => entry.trim().toLowerCase())
      .sort((a, b) => a.localeCompare(b));

    if (Array.isArray(actual)) {
      correct =
        wanted.length === actual.length && wanted.every((entry, index) => entry === actual[index]);
    }
  } else if (typeof actual === "number") {
    const wanted = Number(expected);
    correct = Number.isFinite(wanted) && actual === wanted;
  } else {
    correct = actual === String(expected).trim().toLowerCase();
  }

  return { correct, explanation: question.explanation ?? "" };
}

/** Builds the payload delivered to consumers. */
export function createSurveySubmission(
  survey: SurveyConfig,
  answers: SurveyAnswers,
  context: {
    readonly source?: string | null;
    readonly position?: number;
    readonly duration?: number;
    readonly skipped?: boolean;
    readonly at?: number;
    readonly attempt?: number;
  } = {},
): SurveySubmission {
  return {
    survey,
    answers,
    submittedAt: context.at ?? Date.now(),
    source: context.source ?? null,
    position: context.position ?? 0,
    duration: context.duration ?? 0,
    skipped: context.skipped ?? false,
    attempt: context.attempt ?? 0,
  };
}

function storageKeyFor(survey: SurveyConfig, source: string | null, override?: string): string {
  if (override !== undefined && override.length > 0) {
    return override;
  }

  if (survey.storageKey !== undefined && survey.storageKey.length > 0) {
    return survey.storageKey;
  }

  return `universal-player:survey:${surveyId(survey)}:${source ?? "unknown"}`;
}

/** Creates a best-effort "already shown" store. */
export function createSurveyStore(
  survey: SurveyConfig,
  source: string | null,
  options: SurveyStoreOptions = {},
): SurveyStore {
  const key = storageKeyFor(survey, source, options.key);

  const resolveStorage = (): Storage | null => {
    if (options.storage !== undefined) {
      return options.storage;
    }

    try {
      return typeof localStorage === "undefined" ? null : localStorage;
    } catch {
      return null;
    }
  };

  return {
    key,
    wasShown(): boolean {
      const storage = resolveStorage();

      if (storage === null) {
        return false;
      }

      try {
        return storage.getItem(key) === "1";
      } catch {
        return false;
      }
    },
    markShown(): void {
      const storage = resolveStorage();

      if (storage === null) {
        return;
      }

      try {
        storage.setItem(key, "1");
      } catch {
        // Persistence is best-effort.
      }
    },
    clear(): void {
      const storage = resolveStorage();

      if (storage === null) {
        return;
      }

      try {
        storage.removeItem(key);
      } catch {
        // Persistence is best-effort.
      }
    },
  };
}
